new = """// A FIB record is 'ADDRESS/LENGTH NEXT_HOP' with spaces, tabs and carriage
// returns as whitespace.  The record is therefore parsed structurally: the
// address runs up to the first '/', the prefix length up to the next
// whitespace, and the remainder must be exactly one next-hop token.  Nothing
// outside that grammar (extra tokens, comments, signs, overflow) is accepted.
struct FibRecord {
    const char* addr;
    size_t addr_len;
    const char* len;
    size_t len_len;
    const char* hop;
    size_t hop_len;
};

bool parse_fib_record(const std::string& line, FibRecord& rec) {
    size_t b = 0;
    size_t e = line.size();
    while (b < e && is_ws(line[b])) ++b;
    while (e > b && is_ws(line[e - 1])) --e;
    if (b == e) return false;  // blank line
    size_t slash = std::string::npos;
    for (size_t i = b; i < e; ++i) {
        if (line[i] == '/') {
            slash = i;
            break;
        }
    }
    if (slash == std::string::npos || slash == b) return false;
    size_t ae = slash;
    while (ae > b && is_ws(line[ae - 1])) --ae;
    size_t ls = slash + 1;
    size_t le = ls;
    while (le < e && !is_ws(line[le])) ++le;
    if (le == ls) return false;  // empty prefix length
    size_t rs = le;
    while (rs < e && is_ws(line[rs])) ++rs;
    if (rs == e) return false;  // missing next hop
    size_t re = rs;
    while (re < e && !is_ws(line[re])) ++re;
    for (size_t i = re; i < e; ++i)
        if (!is_ws(line[i])) return false;  // extra tokens / comments
    rec.addr = line.data() + b;
    rec.addr_len = ae - b;
    rec.len = line.data() + ls;
    rec.len_len = le - ls;
    rec.hop = line.data() + rs;
    rec.hop_len = re - rs;
    return true;
}

